  'RATE_LIMIT',
  'PERMISSION',
  'CHANNEL_UNAVAILABLE',
  'CONVERSATION_STATE',
  'NETWORK',
  'CONFIG',
  'GATEWAY',
  'BILLING',
  'OVERLOADED',
  'MODEL_NOT_FOUND',
  'UNKNOWN',
] as const satisfies readonly AppErrorCode[];

/** The only operations an error may ask a host to perform. */
export type ErrorNextActionKind =
  | 'retry'
  | 'reauthenticate'
  | 'reconfigure'
  | 'open-settings'
  | 'contact-support';

/**
 * A bounded, host-owned action descriptor. `target` identifies a named host
 * surface only; it is never a command, script, shell expression, or argument
 * list.
 */
export type ErrorNextAction = {
  kind: ErrorNextActionKind;
  target?: 'authentication' | 'model' | 'permissions' | 'configuration';
};

/** Where recovery is permitted to occur. */
export type ErrorRecoveryScope = 'self' | 'user' | 'support' | 'none';

export type ErrorRecovery = {
  retryable: boolean;
  scope: ErrorRecoveryScope;
  action?: ErrorNextAction;
};

/**
 * Stable recovery policy for every AppErrorCode. Only transient, self-retryable
 * failures may use retry. UNKNOWN deliberately has no action: its original
 * error must be exposed to the user rather than presenting a fabricated fix.
 */
export const APP_ERROR_RECOVERY: Record<AppErrorCode, ErrorRecovery> = {
  AUTH_INVALID: { retryable: false, scope: 'user', action: { kind: 'reauthenticate', target: 'authentication' } },
  AUTH_PERMANENT: { retryable: false, scope: 'user', action: { kind: 'reauthenticate', target: 'authentication' } },
  TIMEOUT: { retryable: true, scope: 'self', action: { kind: 'retry' } },
  RATE_LIMIT: { retryable: true, scope: 'self', action: { kind: 'retry' } },
  PERMISSION: { retryable: false, scope: 'user', action: { kind: 'open-settings', target: 'permissions' } },
  CHANNEL_UNAVAILABLE: { retryable: false, scope: 'support', action: { kind: 'contact-support' } },
  CONVERSATION_STATE: { retryable: true, scope: 'self', action: { kind: 'retry' } },
  NETWORK: { retryable: true, scope: 'self', action: { kind: 'retry' } },
  CONFIG: { retryable: false, scope: 'user', action: { kind: 'reconfigure', target: 'configuration' } },
  GATEWAY: { retryable: true, scope: 'self', action: { kind: 'retry' } },
  BILLING: { retryable: false, scope: 'user', action: { kind: 'open-settings', target: 'configuration' } },
  OVERLOADED: { retryable: true, scope: 'self', action: { kind: 'retry' } },
  MODEL_NOT_FOUND: { retryable: false, scope: 'user', action: { kind: 'reconfigure', target: 'model' } },
  UNKNOWN: { retryable: false, scope: 'none' },
