      ?? readStatusField(source, 'statusCode')
      ?? readStatusField(source, 'httpStatus');
    signals.reason ??= readStringField(source, 'reason')
      ?? readStringField(source, 'type')
      ?? readStringField(source, 'errorType');
  }
